import json,sys,os,glob
from datetime import datetime

def ts(s):
    return datetime.fromisoformat(s.replace('Z','+00:00'))

D='/tmp/claude-0/-home-user-ClaudiniteWebsite/427ee00f-3f17-50d0-a1b6-c582deac95db/scratchpad/logs'
for path in sorted(glob.glob(D+'/*.jsonl')):
    name=os.path.basename(path)
    entries=[]
    for line in open(path):
        line=line.strip()
        if not line: continue
        try: entries.append(json.loads(line))
        except: pass
    # user human turns
    human=[]
    toolcalls=[]  # (ts, name, id)
    toolresults={}
    batches=[]
    first=last=None
    for e in entries:
        t=e.get('timestamp')
        if t:
            tt=ts(t)
            if first is None: first=tt
            last=tt
        m=e.get('message') or {}
        role=m.get('role')
        c=m.get('content')
        if role=='user':
            if isinstance(c,str):
                human.append((t,c))
            elif isinstance(c,list):
                txt=[b.get('text','') for b in c if isinstance(b,dict) and b.get('type')=='text']
                if txt: human.append((t,'\n'.join(txt)))
                for b in c:
                    if isinstance(b,dict) and b.get('type')=='tool_result':
                        toolresults[b.get('tool_use_id')]=t
        elif role=='assistant' and isinstance(c,list):
            tus=[b for b in c if isinstance(b,dict) and b.get('type')=='tool_use']
            if tus:
                batches.append(len(tus))
                for b in tus:
                    toolcalls.append((t,b.get('name'),b.get('id')))
    # exec time & overhead
    exec_s=0.0
    for t,n,i in toolcalls:
        if i in toolresults and t and toolresults[i]:
            d=(ts(toolresults[i])-ts(t)).total_seconds()
            if d>0: exec_s+=d
    total=(last-first).total_seconds() if first and last else 0
    print('='*100)
    print('FILE',name)
    print('entries',len(entries),'assistant tool msgs',len(batches),'tool calls',len(toolcalls),
          'batched(>1)',sum(1 for b in batches if b>1),'maxbatch',max(batches) if batches else 0)
    print('span_s %.0f exec_s %.0f overhead_s %.0f'%(total,exec_s,total-exec_s))
    # biggest idle gaps
    gaps=[]
    prev=None
    for e in entries:
        t=e.get('timestamp')
        if not t: continue
        tt=ts(t)
        if prev: gaps.append(((tt-prev).total_seconds(),prev.isoformat(),tt.isoformat()))
        prev=tt
    gaps.sort(reverse=True)
    print('top gaps:',[('%.0fs'%g[0],g[1][11:19]) for g in gaps[:5]])
    from collections import Counter
    print('tools:',Counter(n for _,n,_ in toolcalls).most_common(12))
    print('--- HUMAN TURNS (%d) ---'%len(human))
    for t,txt in human:
        print('[%s] %s'%(t, txt[:1500].replace('\n',' | ')))

import json,sys,glob,os
D='/tmp/claude-0/-home-user-ClaudiniteWebsite/427ee00f-3f17-50d0-a1b6-c582deac95db/scratchpad/logs'
pat=sys.argv[1]
mode=sys.argv[2] if len(sys.argv)>2 else 'errors'
for path in sorted(glob.glob(D+'/*'+pat+'*.jsonl')):
    print('#'*80); print(os.path.basename(path))
    ents=[json.loads(l) for l in open(path) if l.strip()]
    for e in ents:
        m=e.get('message') or {}
        r=m.get('role'); c=m.get('content'); t=e.get('timestamp','')
        if r=='assistant' and isinstance(c,list):
            for b in c:
                if b.get('type')=='text' and mode in ('text','all'):
                    print('\n[A %s] %s'%(t[11:19],b['text'][:2500]))
                if b.get('type')=='tool_use' and mode in ('tools','all'):
                    inp=json.dumps(b.get('input'))[:400]
                    print('[T %s] %s %s'%(t[11:19],b.get('name'),inp))
        if r=='user' and isinstance(c,list):
            for b in c:
                if b.get('type')=='tool_result':
                    ct=b.get('content')
                    s=ct if isinstance(ct,str) else json.dumps(ct)
                    if b.get('is_error') and mode in ('errors','all','tools'):
                        print('[ERR %s] %s'%(t[11:19],s[:700]))
                    elif mode=='all':
                        print('[R %s] %s'%(t[11:19],s[:300]))
                elif b.get('type')=='text' and mode in ('text','all','errors'):
                    print('\n>>> [USER %s] %s'%(t[11:19],b['text'][:4000]))
        if r=='user' and isinstance(c,str) and mode in ('text','all','errors'):
            print('\n>>> [USER %s] %s'%(t[11:19],c[:4000]))

